from __future__ import annotations

import re

from relocation_jobs.team_docs import repo

_TITLE_MAX = 200
_SLUG_MAX = 80
_BODY_MAX = 200_000

FOLDERS = {
    "product": "Product",
    "business": "Business",
    "marketing": "Marketing",
    "tech": "Tech",
}


def _clean_title(title: str) -> str:
    cleaned = " ".join((title or "").split())
    if not cleaned:
        raise ValueError("Title is required")
    if len(cleaned) > _TITLE_MAX:
        raise ValueError(f"Title must be at most {_TITLE_MAX} characters")
    return cleaned


def _slugify(value: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]+", "-", (value or "").strip().lower()).strip("-")
    cleaned = cleaned[:_SLUG_MAX].strip("-")
    if not cleaned:
        raise ValueError("A URL-safe slug is required")
    return cleaned


def _clean_body(body) -> str:
    text = "" if body is None else str(body)
    if len(text) > _BODY_MAX:
        raise ValueError(f"Body must be at most {_BODY_MAX} characters")
    return text


def _allocate_slug(folder: str, slug: str) -> str:
    if not repo.find_doc_in_folder(folder, slug):
        return slug
    index = 2
    while True:
        candidate = f"{slug}-{index}"
        if not repo.find_doc_in_folder(folder, candidate):
            return candidate
        index += 1


def _require_folder(folder: str) -> str:
    slug = (folder or "").strip()
    if slug not in FOLDERS:
        raise LookupError("Folder not found")
    return slug


def _with_path(doc: dict) -> dict:
    folder = doc["folder"]
    return {**doc, "path": f"/{folder}/{doc['slug']}", "folder_path": f"/{folder}"}


def list_folder_tree() -> dict:
    by_folder: dict[str, list[dict]] = {}
    for doc in repo.list_doc_summaries():
        by_folder.setdefault(doc["folder"], []).append(_with_path(doc))
    return {
        "folders": [
            {
                "slug": slug,
                "title": title,
                "path": f"/{slug}",
                "docs": by_folder.get(slug, []),
            }
            for slug, title in FOLDERS.items()
        ]
    }


def get_document(doc_id: int) -> dict:
    doc = repo.get_doc(doc_id)
    if not doc:
        raise LookupError("Document not found")
    return _with_path(doc)


def create_document(
    *,
    folder: str,
    title: str,
    body: str = "",
    slug: str | None = None,
) -> dict:
    folder = _require_folder(folder)
    clean_title = _clean_title(title)
    requested = (slug or "").strip()
    base = _slugify(requested or clean_title)
    allocated = _allocate_slug(folder, base) if not requested else base
    if requested and repo.find_doc_in_folder(folder, allocated):
        raise ValueError("A document with that slug already exists in this folder")
    saved = repo.insert_doc(
        folder=folder,
        slug=allocated,
        title=clean_title,
        body=_clean_body(body),
    )
    return _with_path(saved)


def update_document(
    doc_id: int,
    *,
    title: str | None = None,
    body: str | None = None,
    slug: str | None = None,
    folder: str | None = None,
) -> dict:
    current = repo.get_doc(doc_id)
    if not current:
        raise LookupError("Document not found")
    next_folder = _require_folder(folder) if folder is not None else current["folder"]
    next_title = _clean_title(title) if title is not None else current["title"]
    next_body = _clean_body(body) if body is not None else current["body"]
    requested = None if slug is None else str(slug).strip()
    if requested == "":
        raise ValueError("A URL-safe slug is required")
    next_slug = _slugify(requested) if requested else current["slug"]
    clash = repo.find_doc_in_folder(next_folder, next_slug)
    if clash and clash["id"] != current["id"]:
        raise ValueError("A document with that slug already exists in this folder")
    saved = repo.update_doc(
        current["id"],
        folder=next_folder,
        slug=next_slug,
        title=next_title,
        body=next_body,
    )
    if not saved:
        raise LookupError("Document not found")
    return _with_path(saved)


def delete_document(doc_id: int) -> None:
    if not repo.delete_doc(doc_id):
        raise LookupError("Document not found")

from __future__ import annotations

from flask import jsonify, request

from relocation_jobs.core.auth import admin_required
from relocation_jobs.team_docs import service as team_docs_service


def register(app):
    @app.get("/api/admin/team-docs")
    @admin_required
    def api_admin_team_docs_tree():
        return jsonify(team_docs_service.list_folder_tree())

    @app.post("/api/admin/team-docs")
    @admin_required
    def api_admin_create_team_doc():
        body = request.get_json(silent=True) or {}
        folder = str(body.get("folder") or "").strip()
        if not folder:
            return jsonify({"error": "folder is required"}), 400
        try:
            saved = team_docs_service.create_document(
                folder=folder,
                title=str(body.get("title") or ""),
                body=body.get("body") or "",
                slug=(body.get("slug") or None),
            )
            return jsonify({"ok": True, "doc": saved}), 201
        except (TypeError, ValueError) as exc:
            return jsonify({"error": str(exc)}), 400
        except LookupError as exc:
            return jsonify({"error": str(exc)}), 404

    @app.get("/api/admin/team-docs/<int:doc_id>")
    @admin_required
    def api_admin_get_team_doc(doc_id: int):
        try:
            return jsonify({"doc": team_docs_service.get_document(doc_id)})
        except LookupError as exc:
            return jsonify({"error": str(exc)}), 404

    @app.patch("/api/admin/team-docs/<int:doc_id>")
    @admin_required
    def api_admin_update_team_doc(doc_id: int):
        body = request.get_json(silent=True) or {}
        folder = None
        if "folder" in body:
            folder = str(body.get("folder") or "").strip() or None
        try:
            saved = team_docs_service.update_document(
                doc_id,
                title=None if "title" not in body else str(body.get("title") or ""),
                body=None if "body" not in body else body.get("body"),
                slug=None if "slug" not in body else body.get("slug"),
                folder=folder,
            )
            return jsonify({"ok": True, "doc": saved})
        except (TypeError, ValueError) as exc:
            return jsonify({"error": str(exc)}), 400
        except LookupError as exc:
            return jsonify({"error": str(exc)}), 404

    @app.delete("/api/admin/team-docs/<int:doc_id>")
    @admin_required
    def api_admin_delete_team_doc(doc_id: int):
        try:
            team_docs_service.delete_document(doc_id)
            return jsonify({"ok": True})
        except LookupError as exc:
            return jsonify({"error": str(exc)}), 404

import { $, escapeHtml, toast } from "./utils.js";

let tree = { folders: [] };
let selected = { folder: null, docId: null };
let bound = false;

async function apiJson(path, options = {}) {
  const res = await fetch(path, {
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", ...(options.headers || {}) },
    ...options,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
  return data;
}

function selectedFolder() {
  return tree.folders.find((folder) => folder.slug === selected.folder) || null;
}

function renderTree(folders) {
  return (folders || []).map((folder) => {
    const activeFolder = selected.folder === folder.slug && !selected.docId;
    const docs = (folder.docs || []).map((doc) => {
      const active = selected.docId === doc.id;
      return `
        <button type="button" class="admin-docs-item${active ? " is-active" : ""}" data-doc-id="${doc.id}" data-folder="${escapeHtml(folder.slug)}">
          ${escapeHtml(doc.title)}
        </button>`;
    }).join("");
    return `
      <div class="admin-docs-folder">
        <div class="admin-docs-folder-row">
          <button type="button" class="admin-docs-folder-btn${activeFolder ? " is-active" : ""}" data-folder="${escapeHtml(folder.slug)}">
            ${escapeHtml(folder.path)}
          </button>
          <button type="button" class="secondary-btn admin-docs-new" data-folder="${escapeHtml(folder.slug)}">New</button>
        </div>
        <div class="admin-docs-children">
          ${docs || `<p class="hint admin-docs-empty">Empty folder</p>`}
        </div>
      </div>`;
  }).join("");
}

function editorHtml() {
  const folder = selectedFolder();
  const folderOptions = tree.folders.map((item) => (
    `<option value="${escapeHtml(item.slug)}" ${item.slug === selected.folder ? "selected" : ""}>${escapeHtml(item.path)}</option>`
  )).join("");
  if (!folder) {
    return `<p class="hint">Select a folder to add a markdown doc, or open an existing one.</p>`;
  }
  const creating = !selected.docId;
  return `
    <form class="admin-docs-form" id="adminDocsForm">
      <label>
        <span>Folder</span>
        <select name="folder">${folderOptions}</select>
      </label>
      <label>
        <span>Title</span>
        <input name="title" type="text" maxlength="200" required placeholder="Doc title" />
      </label>
      <label>
        <span>Slug</span>
        <input name="slug" type="text" maxlength="80" placeholder="auto-from-title" ${creating ? "" : "required"} />
      </label>
      <label class="admin-docs-body-label">
        <span>Markdown</span>
        <textarea name="body" rows="18" spellcheck="false" placeholder="# Heading&#10;&#10;Write markdown…"></textarea>
      </label>
      <div class="admin-docs-actions">
        <button type="submit" class="primary">${creating ? "Create" : "Save"}</button>
        <button type="button" class="secondary-btn" id="adminDocsDelete" ${creating ? "hidden" : ""}>Delete</button>
        <p class="hint" id="adminDocsPath"></p>
      </div>
    </form>`;
}

function fillForm(doc) {
  const form = $("adminDocsForm");
  if (!form) return;
  form.title.value = doc?.title || "";
  form.slug.value = doc?.slug || "";
  form.body.value = doc?.body || "";
  if (doc?.folder) form.folder.value = doc.folder;
  const path = $("adminDocsPath");
  if (path) path.textContent = doc?.path || selectedFolder()?.path || "";
}

function bindMount(mount) {
  if (bound) return;
  bound = true;
  mount.addEventListener("click", async (event) => {
    if (event.target.id === "adminDocsDelete") {
      await deleteSelected();
      return;
    }
    const newBtn = event.target.closest(".admin-docs-new");
    if (newBtn) {
      selected = { folder: newBtn.dataset.folder, docId: null };
      render();
      return;
    }
    const docBtn = event.target.closest("[data-doc-id]");
    if (docBtn) {
      selected = { folder: docBtn.dataset.folder, docId: Number(docBtn.dataset.docId) };
      await loadSelected();
      return;
    }
    const folderBtn = event.target.closest("[data-folder].admin-docs-folder-btn");
    if (folderBtn) {
      selected = { folder: folderBtn.dataset.folder, docId: null };
      render();
    }
  });
  mount.addEventListener("submit", async (event) => {
    if (event.target.id !== "adminDocsForm") return;
    event.preventDefault();
    await saveForm(event.target);
  });
}

async function loadSelected() {
  const mount = $("adminTeamDocs");
  if (!selected.docId) {
    render();
    return;
  }
  try {
    const data = await apiJson(`/api/admin/team-docs/${selected.docId}`);
    selected.folder = data.doc.folder;
    render();
    fillForm(data.doc);
  } catch (err) {
    render();
    toast(err.message || "Could not load document");
  }
  mount?.querySelector("#adminDocsForm input[name='title']")?.focus();
}

async function saveForm(form) {
  const payload = {
    folder: form.folder.value,
    title: form.title.value,
    slug: form.slug.value.trim(),
    body: form.body.value,
  };
  if (!payload.slug) delete payload.slug;
  try {
    const creating = !selected.docId;
    const saved = creating
      ? await apiJson("/api/admin/team-docs", {
        method: "POST",
        body: JSON.stringify(payload),
      })
      : await apiJson(`/api/admin/team-docs/${selected.docId}`, {
        method: "PATCH",
        body: JSON.stringify(payload),
      });
    selected = { folder: saved.doc.folder, docId: saved.doc.id };
    tree = await apiJson("/api/admin/team-docs");
    render();
    fillForm(saved.doc);
    toast(creating ? "Created" : "Saved");
  } catch (err) {
    toast(err.message || "Could not save");
  }
}

async function deleteSelected() {
  if (!selected.docId) return;
  if (!window.confirm("Delete this document?")) return;
  try {
    await apiJson(`/api/admin/team-docs/${selected.docId}`, { method: "DELETE" });
    const folder = selected.folder;
    selected = { folder, docId: null };
    tree = await apiJson("/api/admin/team-docs");
    render();
    toast("Deleted");
  } catch (err) {
    toast(err.message || "Could not delete");
  }
}

function render() {
  const mount = $("adminTeamDocs");
  if (!mount) return;
  mount.innerHTML = `
    <section class="admin-panel admin-docs">
      <div class="admin-docs-tree">
        <h2 class="admin-panel-title">Folders</h2>
        <p class="hint">Staff-only markdown. Empty folders are expected until you add docs.</p>
        ${renderTree(tree.folders) || `<p class="hint">No folders yet.</p>`}
      </div>
      <div class="admin-docs-editor">
        <h2 class="admin-panel-title">${selected.docId ? "Edit markdown" : "New markdown"}</h2>
        ${editorHtml()}
      </div>
    </section>`;
  bindMount(mount);
}

export async function loadTeamDocsPane() {
  tree = await apiJson("/api/admin/team-docs");
  if (!selected.folder && tree.folders[0]) {
    selected = { folder: tree.folders[0].slug, docId: null };
  }
  render();
  if (selected.docId) await loadSelected();
}
